import { useEffect, useRef, useState } from "react";
import { Coffee } from "lucide-react";

type Item = {
  name: string;
  note: string;
  price: string;
};

const BAR: Item[] = [
  { name: "Espresso", note: "Alder St. blend · Brazil, Ethiopia · 18g in, 36g out", price: "3.50" },
  { name: "Macchiato", note: "Two ounces, one spoon of foam", price: "3.75" },
  { name: "Cortado", note: "Four ounces, milk silk at 62°", price: "4.25" },
  { name: "Filter", note: "Batch brew, single origin, changes Wednesday", price: "4.00" },
  { name: "Cold Brew", note: "Eighteen-hour steep, poured on nitro", price: "5.00" },
];

const RETAIL: Item[] = [
  { name: "Whole bean, 250g", note: "Roasted Tuesday, on the shelf Wednesday", price: "18.00" },
  { name: "Whole bean, 1kg", note: "Standing order, delivered first Friday", price: "58.00" },
];

function Row({ item, index }: { item: Item; index: number }) {
  return (
    <li
      className="row border-b border-warmgrey/45 py-4 opacity-0"
      style={{ animationDelay: `${120 + index * 70}ms` }}
    >
      <div className="flex items-baseline gap-3">
        <span className="text-[1.0625rem] font-semibold tracking-tight text-ink sm:text-[1.1875rem]">
          {item.name}
        </span>
        <span
          aria-hidden="true"
          className="min-w-6 flex-1 translate-y-[-0.3em] border-b border-dotted border-warmgrey"
        />
        <span className="nums text-[1.0625rem] font-semibold text-ink sm:text-[1.1875rem]">
          {item.price}
        </span>
      </div>
      <p className="mt-1.5 max-w-[52ch] text-[13px] leading-relaxed text-muted">{item.note}</p>
    </li>
  );
}

export default function Menu() {
  const ref = useRef<HTMLElement | null>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const io = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          setShown(true);
          io.disconnect();
        }
      },
      { threshold: 0.15 },
    );
    io.observe(node);
    return () => io.disconnect();
  }, []);

  return (
    <section
      id="menu"
      ref={ref}
      className={`relative border-t border-ink/25 bg-paper-deep/70 px-5 py-16 sm:px-8 lg:px-12 lg:py-24 ${
        shown ? "in-view" : ""
      }`}
    >
      <div className="mx-auto grid max-w-[1600px] gap-10 lg:grid-cols-[18rem_1fr] lg:gap-16">
        {/* sticky label rail */}
        <div className="lg:sticky lg:top-28 lg:self-start">
          <div className="flex items-center gap-3">
            <Coffee className="h-5 w-5 text-stamp" strokeWidth={1.75} />
            <span className="smallcaps text-muted">The list</span>
          </div>
          <h2 className="mt-4 font-display text-[3.5rem] font-black leading-[0.85] tracking-[-0.03em] text-ink lg:text-[4.5rem]">
            Menu
          </h2>
          <div className="drawrule mt-6 h-px w-full bg-ink/40" />
          <p className="mt-5 max-w-[30ch] text-[13px] leading-relaxed text-muted">
            Prices in dollars, tax included. Oat, skim and half-and-half at no charge. Cash and
            card, no minimum.
          </p>
        </div>

        <div>
          <p className="smallcaps mb-2 text-stamp">At the bar</p>
          <ul className="border-t border-ink/25">
            {BAR.map((item, i) => (
              <Row key={item.name} item={item} index={i} />
            ))}
          </ul>

          <p className="smallcaps mb-2 mt-12 text-stamp">To take home</p>
          <ul className="border-t border-ink/25">
            {RETAIL.map((item, i) => (
              <Row key={item.name} item={item} index={i + BAR.length} />
            ))}
          </ul>

          <p className="mt-8 max-w-[54ch] font-display text-[1.0625rem] italic leading-relaxed text-ink-mid">
            &ldquo;If it isn&rsquo;t right, say so at the counter and we&rsquo;ll make it again —
            no debate, no coupon.&rdquo;
          </p>
        </div>
      </div>
    </section>
  );
}

